class EscPosPrinterService(
    private val printerDpi: Int = PrinterConfig.DPI,
    private val printerWidthMm: Float = PrinterConfig.WIDTH_MM,
    private val charsPerLine: Int = PrinterConfig.CHARS_PER_LINE,
