// Presentation of a kitchen-api order status on the display board.
//
// Statuses come straight from kitchen-api's `OrderStatusEnum`
// (DRAFT → CONFIRMED → IN_PROCESS_OF_DELIVERY → DELIVERED, plus CANCELLED) so a
// real order event can be shown here without translation. The board only shows
// tickets that are actively being worked — CONFIRMED and IN_PROCESS_OF_DELIVERY.
// DRAFT isn't a real order yet; DELIVERED/CANCELLED are done and leave the board.

/** Statuses that appear on the board. Order here is NOT how cards are sorted. */
export const BOARD_STATUSES = ["CONFIRMED", "IN_PROCESS_OF_DELIVERY"];

/** Whether a ticket with this status belongs on the board at all. */
export function isBoardVisible(status) {
  return BOARD_STATUSES.includes(status);
}

/**
 * The badge shown INSIDE the ticket for a given status. `tone` is a CSS hook,
 * `label` is Spanish to match the Mexican-kitchen codebase. A pickup order that
 * is ready says "recoger" (collect); a delivery order says "envío" (ship).
 */
export function statusBadge(status, deliveryType) {
  switch (status) {
    case "CONFIRMED":
      return { key: "CONFIRMED", label: "Preparando", tone: "preparing" };
    case "IN_PROCESS_OF_DELIVERY":
      return deliveryType === "DELIVERY"
        ? { key: "READY", label: "Listo para envío", tone: "ready" }
        : { key: "READY", label: "Listo para recoger", tone: "ready" };
    case "DELIVERED":
      return { key: "DELIVERED", label: "Entregado", tone: "done" };
    case "CANCELLED":
      return { key: "CANCELLED", label: "Cancelado", tone: "cancelled" };
    case "DRAFT":
      return { key: "DRAFT", label: "Borrador", tone: "neutral" };
    default:
      return { key: String(status), label: String(status), tone: "neutral" };
  }
}

/** Short human label for the fulfilment type, shown in the collapsed summary. */
export function deliveryLabel(deliveryType) {
  if (deliveryType === "DELIVERY") return "Envío";
  if (deliveryType === "PICKUP") return "Recoger";
  return "—";
}

// In-memory order board, keyed by order number.
//
// This is the whole "grouping" model: there are NO per-status lists. Every
// ticket lives in one collection and is always returned sorted by order number
// ascending. A status change mutates the ticket in place — it never moves the
// ticket to another bucket, which is exactly the behaviour the board relies on
// so a card keeps its position when its badge flips from "Preparando" to
// "Listo".
//
// Pure and dependency-free so it can be unit-tested with `node --test` without a
// server, a socket, or a database.

import { isBoardVisible } from "./status.mjs";

function toOrderNumber(value) {
  const parsed = Number(value);
  if (!Number.isInteger(parsed)) {
    throw new Error(`order requires an integer orderNumber, received: ${value}`);
  }
  return parsed;
}

function normalizeItems(items) {
  if (!Array.isArray(items)) return [];
  return items.map((item) => ({
    name: String(item?.name ?? item?.nameSnapshot ?? "Producto"),
    quantity: Number.isInteger(item?.quantity) ? item.quantity : 1,
    unitPrice: Number(item?.unitPrice ?? item?.unitPriceSnapshot ?? 0)
  }));
}

function computeTotal(order, items) {
  if (typeof order?.total === "number") return order.total;
  return items.reduce((sum, item) => sum + item.unitPrice * item.quantity, 0);
}

/** Coerce a raw order (e.g. a kitchen-api payload) into the board's shape. */
export function normalizeOrder(order) {
  const orderNumber = toOrderNumber(order?.orderNumber);
  const items = normalizeItems(order?.items);
  return {
    orderNumber,
    id: order?.id != null ? String(order.id) : String(orderNumber),
    status: String(order?.status ?? "CONFIRMED"),
    deliveryType: order?.deliveryType ?? null,
    items,
    total: computeTotal(order, items),
    clientName: order?.clientName ? String(order.clientName) : null,
    updatedAt: order?.updatedAt ?? new Date().toISOString()
  };
}

export class OrderStore {
  constructor() {
    /** @type {Map<number, object>} */
    this.byNumber = new Map();
  }

  /** Insert or replace a ticket. Returns the normalized order that was stored. */
  upsert(rawOrder) {
    const order = normalizeOrder(rawOrder);
    this.byNumber.set(order.orderNumber, order);
    return order;
  }

  /**
   * Change a ticket's status in place. Returns
   * `{ changed: false }` if the order isn't on the board, otherwise
   * `{ changed: true, order, previousStatus }`. The order's position in
   * `list()`/`board()` is unaffected — it's still sorted by number.
   */
  changeStatus(orderNumber, status) {
    const key = toOrderNumber(orderNumber);
    const current = this.byNumber.get(key);
    if (!current) {
      return { changed: false };
    }
    const previousStatus = current.status;
    const order = { ...current, status: String(status), updatedAt: new Date().toISOString() };
    this.byNumber.set(key, order);
    return { changed: true, order, previousStatus };
  }

  get(orderNumber) {
    return this.byNumber.get(toOrderNumber(orderNumber)) ?? null;
  }

  /** Every ticket, sorted by order number ascending (the ONLY sort key). */
  list() {
    return [...this.byNumber.values()].sort((a, b) => a.orderNumber - b.orderNumber);
  }

  /** Board-visible tickets (CONFIRMED / ready), sorted by order number. */
  board() {
    return this.list().filter((order) => isBoardVisible(order.status));
  }

  remove(orderNumber) {
    return this.byNumber.delete(toOrderNumber(orderNumber));
  }
}

// Server-Sent Events fan-out. One hub, many connected dashboard screens.
//
// This is the "live-update subscription logic" the board is built around: the
// browser opens a single EventSource to /events and this hub pushes named
// events (`snapshot`, `order`, `status`) to every connected screen. Kept tiny
// and transport-only so the order model stays testable in isolation.

/** Serialize one SSE frame: `event:` line + one `data:` line of JSON. */
export function formatSseFrame(event, data) {
  return `event: ${event}\n` + `data: ${JSON.stringify(data)}\n\n`;
}

export class SseHub {
  constructor() {
    /** @type {Set<import('node:http').ServerResponse>} */
    this.clients = new Set();
  }

  /**
   * Register a live connection. Writes the SSE headers, keeps the socket open,
   * and removes the client automatically when the screen disconnects.
   */
  addClient(request, response) {
    response.writeHead(200, {
      "Content-Type": "text/event-stream",
      "Cache-Control": "no-cache, no-transform",
      Connection: "keep-alive",
      "X-Accel-Buffering": "no"
    });
    // Comment frame flushes headers immediately and defeats proxy buffering.
    response.write(": connected\n\n");
    this.clients.add(response);

    const drop = () => {
      this.clients.delete(response);
    };
    request.on("close", drop);
    request.on("error", drop);
    response.on("close", drop);
    response.on("error", drop);
  }

  /** Push a named event to every connected screen. */
  broadcast(event, data) {
    const frame = formatSseFrame(event, data);
    for (const client of this.clients) {
      client.write(frame);
    }
  }

  /** Send one event to a single connection (used for the initial snapshot). */
  send(response, event, data) {
    response.write(formatSseFrame(event, data));
  }

  get size() {
    return this.clients.size;
  }
}

// Kitchen orders display board — HTTP + SSE server (zero dependencies).
//
// Endpoints:
//   GET  /                     the dashboard page (single sorted ticket list)
//   GET  /events               SSE stream: `snapshot`, then `order` / `status`
//   GET  /api/orders           current board as JSON (sorted by number)
//   POST /api/orders           ingest/replace one order  -> broadcast `order`
//   POST /api/orders/:n/status change a status in place  -> broadcast `status`
//   POST /api/demo/seed        inject demo tickets (for the McDonald's-style demo)
//   GET  /healthz              liveness probe
//
// kitchen-api (once it grows an outbound webhook) only needs to POST to
// /api/orders and /api/orders/:n/status — the same shape the simulator uses.

import { createServer as createHttpServer } from "node:http";
import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";
import { OrderStore } from "./order-store.mjs";
import { SseHub } from "./sse-hub.mjs";
import { statusBadge, isBoardVisible } from "./status.mjs";
import { startSimulator } from "./simulator.mjs";

const here = path.dirname(fileURLToPath(import.meta.url));
const indexHtmlPath = path.join(here, "public", "index.html");

const CORS_HEADERS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Allow-Headers": "content-type"
};

function sendJson(response, statusCode, body) {
  const payload = JSON.stringify(body);
  response.writeHead(statusCode, { "Content-Type": "application/json", ...CORS_HEADERS });
  response.end(payload);
}

async function readJsonBody(request) {
  const chunks = [];
  for await (const chunk of request) chunks.push(chunk);
  if (chunks.length === 0) return {};
  return JSON.parse(Buffer.concat(chunks).toString("utf8"));
}

/** Snapshot event payload for a freshly connected screen. */
function boardSnapshot(store) {
  return {
    orders: store.board().map((order) => decorate(order))
  };
}

/** Attach the presentational badge so the browser doesn't re-derive it. */
function decorate(order) {
  return { ...order, badge: statusBadge(order.status, order.deliveryType) };
}

/**
 * Build the board server. Returns the http.Server plus its store/hub so tests
 * can drive it directly. Nothing listens until you call `.listen()`.
 */
export function createBoardServer({ enableDemo = false } = {}) {
  const store = new OrderStore();
  const hub = new SseHub();

  function broadcastOrder(order) {
    hub.broadcast("order", decorate(order));
  }

  function broadcastStatus(order) {
    hub.broadcast("status", {
      orderNumber: order.orderNumber,
      status: order.status,
      badge: statusBadge(order.status, order.deliveryType),
      visible: isBoardVisible(order.status)
    });
  }

  const server = createHttpServer(async (request, response) => {
    try {
      const url = new URL(request.url, "http://localhost");
      const { pathname } = url;

      if (request.method === "OPTIONS") {
        response.writeHead(204, CORS_HEADERS);
        return response.end();
      }

      if (request.method === "GET" && pathname === "/healthz") {
        return sendJson(response, 200, { ok: true, clients: hub.size, orders: store.list().length });
      }

      if (request.method === "GET" && (pathname === "/" || pathname === "/index.html")) {
        const html = await readFile(indexHtmlPath, "utf8");
        response.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
        return response.end(html);
      }

      if (request.method === "GET" && pathname === "/events") {
        hub.addClient(request, response);
        hub.send(response, "snapshot", boardSnapshot(store));
        return; // keep the socket open
      }

      if (request.method === "GET" && pathname === "/api/orders") {
        return sendJson(response, 200, boardSnapshot(store));
      }

      if (request.method === "POST" && pathname === "/api/orders") {
        const body = await readJsonBody(request);
        const order = store.upsert(body);
        broadcastOrder(order);
        return sendJson(response, 201, decorate(order));
      }

      const statusMatch = pathname.match(/^\/api\/orders\/(\d+)\/status$/);
      if (request.method === "POST" && statusMatch) {
        const orderNumber = Number(statusMatch[1]);
        const body = await readJsonBody(request);
        const result = store.changeStatus(orderNumber, body?.status);
        if (!result.changed) {
          return sendJson(response, 404, { ok: false, error: "order_not_found", orderNumber });
        }
        broadcastStatus(result.order);
        return sendJson(response, 200, decorate(result.order));
      }

      if (request.method === "POST" && pathname === "/api/demo/seed") {
        const seeded = startSimulator({ store, broadcastOrder, broadcastStatus, once: true });
        return sendJson(response, 200, { ok: true, seeded });
      }

      sendJson(response, 404, { ok: false, error: "not_found" });
    } catch (error) {
      sendJson(response, 400, { ok: false, error: "bad_request", detail: String(error?.message ?? error) });
    }
  });

  let simulatorHandle = null;
  if (enableDemo) {
    simulatorHandle = startSimulator({ store, broadcastOrder, broadcastStatus });
  }
  server.on("close", () => simulatorHandle?.stop?.());

  return { server, store, hub };
}

// Start only when run directly (not when imported by a test).
const isMain = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isMain) {
  const port = Number(process.env.DASHBOARD_PORT || 4321);
  const enableDemo = process.env.DASHBOARD_DEMO === "1";
  const { server } = createBoardServer({ enableDemo });
  server.listen(port, () => {
    // eslint-disable-next-line no-console
    console.log(`[kitchen-dashboard] listening on http://localhost:${port}${enableDemo ? " (demo mode)" : ""}`);
  });
}

// Demo traffic generator — makes the board feel like a real McDonald's/BK
// screen without kitchen-api wired up. Seeds a few tickets and, in live mode,
// keeps adding new orders and advancing existing ones through their lifecycle
// so the SSE stream and the in-place badge updates are visible immediately.
//
// This is DEMO-only. In production the same broadcastOrder/broadcastStatus
// callbacks are driven by real kitchen-api events instead of a timer.

const MENU = [
  "Hamburguesa Clásica",
  "Hamburguesa Doble",
  "Papas Grandes",
  "Nuggets x10",
  "Refresco 600ml",
  "Malteada Vainilla",
  "Ensalada César",
  "Alitas BBQ x8"
];

const DELIVERY_TYPES = ["PICKUP", "DELIVERY"];

function pick(list) {
  return list[Math.floor(Math.random() * list.length)];
}

function randomInt(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

function buildOrder(orderNumber) {
  const itemCount = randomInt(1, 4);
  const items = Array.from({ length: itemCount }, () => {
    const unitPrice = randomInt(35, 180);
    return { name: pick(MENU), quantity: randomInt(1, 3), unitPrice };
  });
  return {
    orderNumber,
    status: "CONFIRMED",
    deliveryType: pick(DELIVERY_TYPES),
    items
  };
}

function nextOrderNumber(store) {
  const numbers = store.list().map((order) => order.orderNumber);
  const highest = numbers.length > 0 ? Math.max(...numbers) : 100;
  return highest + 1;
}

/**
 * Seed the board and (unless `once`) keep it moving.
 * Returns `{ stop }` in live mode, or the number of seeded orders when `once`.
 */
export function startSimulator({ store, broadcastOrder, broadcastStatus, once = false, seedCount = 4 } = {}) {
  const seedOne = () => {
    const order = store.upsert(buildOrder(nextOrderNumber(store)));
    broadcastOrder?.(order);
    return order;
  };

  for (let index = 0; index < seedCount; index += 1) seedOne();

  if (once) return seedCount;

  // Advance one active ticket along CONFIRMED -> ready -> DELIVERED (off board).
  const advance = () => {
    const active = store.board();
    if (active.length === 0) return;
    const target = pick(active);
    const nextStatus =
      target.status === "CONFIRMED" ? "IN_PROCESS_OF_DELIVERY" : "DELIVERED";
    const result = store.changeStatus(target.orderNumber, nextStatus);
    if (result.changed) broadcastStatus?.(result.order);
    if (nextStatus === "DELIVERED") store.remove(target.orderNumber);
  };

  const addTimer = setInterval(() => seedOne(), 9000);
  const advanceTimer = setInterval(advance, 4000);
  addTimer.unref?.();
  advanceTimer.unref?.();

  return {
    stop() {
      clearInterval(addTimer);
      clearInterval(advanceTimer);
    }
  };
}

// Zero-dependency "lint"/"typecheck": parse every source file with the same V8
// parser Node uses, so a syntax error fails CI without pulling in tsc/eslint.
// The app is plain ESM JS (like runtime-config-app), so this is the meaningful
// static check available without an install step.

import { readdir } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { spawnSync } from "node:child_process";
import path from "node:path";

const root = path.dirname(fileURLToPath(import.meta.url));
const dirs = ["../src", "../test", "."].map((d) => path.resolve(root, d));

async function collect(dir) {
  const out = [];
  let entries;
  try {
    entries = await readdir(dir, { withFileTypes: true });
  } catch {
    return out;
  }
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) out.push(...(await collect(full)));
    else if (entry.name.endsWith(".mjs")) out.push(full);
  }
  return out;
}

const files = (await Promise.all(dirs.map(collect))).flat();
let failed = 0;
for (const file of files) {
  const result = spawnSync(process.execPath, ["--check", file], { encoding: "utf8" });
  if (result.status !== 0) {
    failed += 1;
    process.stderr.write(result.stderr || `syntax error in ${file}\n`);
  }
}

if (failed > 0) {
  console.error(`check-syntax: ${failed} file(s) failed`);
  process.exit(1);
}
console.log(`check-syntax: ${files.length} file(s) OK`);

import { test } from "node:test";
import assert from "node:assert/strict";
import { OrderStore, normalizeOrder } from "../src/order-store.mjs";

function confirmed(orderNumber, extra = {}) {
  return { orderNumber, status: "CONFIRMED", deliveryType: "PICKUP", items: [], ...extra };
}

test("list() sorts by order number ascending regardless of insertion order", () => {
  const store = new OrderStore();
  store.upsert(confirmed(103));
  store.upsert(confirmed(101));
  store.upsert(confirmed(102));

  assert.deepEqual(
    store.list().map((o) => o.orderNumber),
    [101, 102, 103]
  );
});

test("upsert on an existing number updates in place and keeps its sorted position", () => {
  const store = new OrderStore();
  store.upsert(confirmed(101));
  store.upsert(confirmed(102));
  store.upsert(confirmed(103));

  // Replace the middle order with new content.
  store.upsert(confirmed(102, { items: [{ name: "Papas", quantity: 2, unitPrice: 50 }] }));

  assert.deepEqual(store.list().map((o) => o.orderNumber), [101, 102, 103]);
  assert.equal(store.get(102).items.length, 1);
  assert.equal(store.byNumber.size, 3, "no duplicate entry created");
});

test("changeStatus updates the badge status in place without moving the card", () => {
  const store = new OrderStore();
  store.upsert(confirmed(101));
  store.upsert(confirmed(102));
  store.upsert(confirmed(103));

  const result = store.changeStatus(102, "IN_PROCESS_OF_DELIVERY");

  assert.equal(result.changed, true);
  assert.equal(result.previousStatus, "CONFIRMED");
  assert.equal(store.get(102).status, "IN_PROCESS_OF_DELIVERY");
  // Position is still purely by number — no per-status regrouping.
  assert.deepEqual(store.list().map((o) => o.orderNumber), [101, 102, 103]);
});

test("changeStatus on an unknown order is a no-op", () => {
  const store = new OrderStore();
  store.upsert(confirmed(101));

  const result = store.changeStatus(999, "DELIVERED");

  assert.equal(result.changed, false);
  assert.equal(store.list().length, 1);
});

test("board() shows only CONFIRMED and IN_PROCESS_OF_DELIVERY, sorted", () => {
  const store = new OrderStore();
  store.upsert(confirmed(101));
  store.upsert(confirmed(102, { status: "IN_PROCESS_OF_DELIVERY" }));
  store.upsert(confirmed(103, { status: "DELIVERED" }));
  store.upsert(confirmed(104, { status: "CANCELLED" }));
  store.upsert(confirmed(100, { status: "DRAFT" }));

  assert.deepEqual(store.board().map((o) => o.orderNumber), [101, 102]);
});

