import { test, before, after } from "node:test";
import assert from "node:assert/strict";
import http from "node:http";
import { createBoardServer } from "../src/server.mjs";

let server;
let base;

before(async () => {
  ({ server } = createBoardServer({ enableDemo: false }));
  await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
  const { port } = server.address();
  base = `http://127.0.0.1:${port}`;
});

after(() => new Promise((resolve) => server.close(resolve)));

function post(pathname, body) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify(body);
    const req = http.request(
      `${base}${pathname}`,
      { method: "POST", headers: { "content-type": "application/json", "content-length": Buffer.byteLength(data) } },
      (res) => {
        const chunks = [];
        res.on("data", (c) => chunks.push(c));
        res.on("end", () => resolve({ status: res.statusCode, body: JSON.parse(Buffer.concat(chunks).toString() || "{}") }));
      }
    );
    req.on("error", reject);
    req.end(data);
  });
}

/** Open the SSE stream and collect parsed {event,data} frames into an array. */
function openStream() {
  const frames = [];
  return new Promise((resolve, reject) => {
    const req = http.get(`${base}/events`, (res) => {
      let buffer = "";
      res.setEncoding("utf8");
      res.on("data", (chunk) => {
        buffer += chunk;
        let sep;
        while ((sep = buffer.indexOf("\n\n")) !== -1) {
          const raw = buffer.slice(0, sep);
          buffer = buffer.slice(sep + 2);
          const eventLine = raw.split("\n").find((l) => l.startsWith("event: "));
          const dataLine = raw.split("\n").find((l) => l.startsWith("data: "));
          if (eventLine) {
            frames.push({
              event: eventLine.slice(7),
              data: dataLine ? JSON.parse(dataLine.slice(6)) : null
            });
          }
        }
      });
      res.on("error", reject);
      resolve({ frames, close: () => req.destroy() });
    });
    req.on("error", reject);
  });
}

async function waitFor(frames, predicate, timeoutMs = 2000) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    const match = frames.find(predicate);
    if (match) return match;
    await new Promise((r) => setTimeout(r, 15));
  }
  throw new Error("timed out waiting for SSE frame; got: " + JSON.stringify(frames));
}

test("a new subscriber receives a snapshot event first", async () => {
  const { frames, close } = await openStream();
  const snapshot = await waitFor(frames, (f) => f.event === "snapshot");
  assert.ok(Array.isArray(snapshot.data.orders));
  close();
});

test("posting an order broadcasts an 'order' frame to subscribers", async () => {
  const { frames, close } = await openStream();
  await waitFor(frames, (f) => f.event === "snapshot");

  const res = await post("/api/orders", {
    orderNumber: 501,
    status: "CONFIRMED",
    deliveryType: "PICKUP",
    items: [{ name: "Hamburguesa", quantity: 1, unitPrice: 80 }]
  });
  assert.equal(res.status, 201);

  const frame = await waitFor(frames, (f) => f.event === "order" && f.data.orderNumber === 501);
  assert.equal(frame.data.badge.tone, "preparing");
  close();
});

test("a status change broadcasts a 'status' frame with the new badge, in place", async () => {
  await post("/api/orders", { orderNumber: 502, status: "CONFIRMED", deliveryType: "PICKUP", items: [] });
  const { frames, close } = await openStream();
  await waitFor(frames, (f) => f.event === "snapshot");

  const res = await post("/api/orders/502/status", { status: "IN_PROCESS_OF_DELIVERY" });
  assert.equal(res.status, 200);

  const frame = await waitFor(frames, (f) => f.event === "status" && f.data.orderNumber === 502);
  assert.equal(frame.data.status, "IN_PROCESS_OF_DELIVERY");
  assert.equal(frame.data.badge.label, "Listo para recoger");
  assert.equal(frame.data.visible, true);
  close();
});

test("moving to DELIVERED marks the ticket not visible so the board drops it", async () => {
  await post("/api/orders", { orderNumber: 503, status: "IN_PROCESS_OF_DELIVERY", deliveryType: "PICKUP", items: [] });
  const { frames, close } = await openStream();
  await waitFor(frames, (f) => f.event === "snapshot");

  await post("/api/orders/503/status", { status: "DELIVERED" });

  const frame = await waitFor(frames, (f) => f.event === "status" && f.data.orderNumber === 503);
  assert.equal(frame.data.visible, false);
  close();
});

