import { config } from "../../infrastructure/config";

// Pushes order events to the kitchen-dashboard display board (KDS).
//
// The board is fed by a single endpoint: `POST {url}/api/orders` with the full
// order snapshot. The board itself is lifecycle-aware — a board-visible status
// shows/updates the ticket, a terminal status (DELIVERED/CANCELLED) drops it —
// so kitchen-api just pushes the current snapshot on every status change and
// lets the board decide what to render.
//
// This is intentionally best-effort and fully decoupled: if the board is down
// or `KITCHEN_DASHBOARD_URL` is unset, the push is a no-op and the order flow is
// never affected.

export interface BoardItem {
  name: string;
  quantity: number;
  unitPrice: number;
}

export interface BoardPayload {
  orderNumber: number;
  status: string;
  deliveryType: string | null;
  items: BoardItem[];
  total: number;
}

export interface NotifyOptions {
  url?: string;
  timeoutMs?: number;
  fetchImpl?: typeof fetch;
  logger?: { warn?: (message: string) => void };
}

/**
 * Map an order (as returned by the order repository) onto the board payload.
 * Returns null for anything that can't live on the board — most importantly an
 * order without an integer `orderNumber` (a DRAFT that was never confirmed).
 */
export function buildBoardPayload(order: any): BoardPayload | null {
  if (order == null) {
    return null;
  }

  const orderNumber = Number(order.orderNumber);
  if (!Number.isInteger(orderNumber)) {
    return null;
  }

  const items: BoardItem[] = Array.isArray(order.items)
    ? order.items.map((item: any) => ({
        name: String(item?.name ?? item?.nameSnapshot ?? "Producto"),
        quantity: Number.isInteger(item?.quantity) ? item.quantity : 1,
        unitPrice: Number(item?.unitPrice ?? item?.unitPriceSnapshot ?? 0)
      }))
    : [];

  const total =
    typeof order.total === "number"
      ? order.total
      : items.reduce((sum, item) => sum + item.unitPrice * item.quantity, 0);

  return {
    orderNumber,
    status: String(order.status),
    deliveryType: order.deliveryType ?? null,
    items,
    total
  };
}

/**
 * Push one order snapshot to the board. Never throws. Returns true only when the
 * board acknowledged the push (2xx). A missing URL, a null payload, a timeout,
 * or any network error resolves to false.
 */
export async function notifyOrderBoard(order: any, options: NotifyOptions = {}): Promise<boolean> {
  const baseUrl = (options.url ?? config.dashboard.url ?? "").trim();
  if (!baseUrl) {
    return false; // integration disabled
  }

  const payload = buildBoardPayload(order);
  if (!payload) {
    return false;
  }

  const fetchImpl = options.fetchImpl ?? (globalThis as any).fetch;
  if (typeof fetchImpl !== "function") {
    return false;
  }

  const timeoutMs = options.timeoutMs ?? config.dashboard.timeoutMs;
  const logger = options.logger ?? console;
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const response = await fetchImpl(`${baseUrl.replace(/\/+$/, "")}/api/orders`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(payload),
      signal: controller.signal
    });
    const ok = typeof response?.ok === "boolean"
      ? response.ok
      : response?.status >= 200 && response?.status < 300;
    if (!ok) {
      logger.warn?.(`[order-board] board rejected push for order #${payload.orderNumber} (status ${response?.status})`);
    }
    return Boolean(ok);
  } catch (error: any) {
    logger.warn?.(`[order-board] push failed for order #${payload.orderNumber}: ${error?.message ?? error}`);
    return false;
  } finally {
    clearTimeout(timer);
  }
}

