import { describe, expect, it, vi } from "vitest";
import {
  buildBoardPayload,
  notifyOrderBoard
} from "../../src/integrations/dashboard/order-board-notifier.ts";

// Order shape as returned by the order repository (mapOrderToContext).
const repoOrder = {
  id: "77",
  orderNumber: 205,
  status: "CONFIRMED",
  deliveryType: "DELIVERY",
  items: [
    { nameSnapshot: "Hamburguesa", quantity: 2, unitPriceSnapshot: 80 },
    { nameSnapshot: "Refresco", quantity: 1, unitPriceSnapshot: 30 }
  ],
  total: 190
};

describe("buildBoardPayload", () => {
  it("maps the repository order onto the board payload", () => {
    const payload = buildBoardPayload(repoOrder);
    expect(payload).toEqual({
      orderNumber: 205,
      status: "CONFIRMED",
      deliveryType: "DELIVERY",
      items: [
        { name: "Hamburguesa", quantity: 2, unitPrice: 80 },
        { name: "Refresco", quantity: 1, unitPrice: 30 }
      ],
      total: 190
    });
  });

  it("computes total from items when the order omits it", () => {
    const { total, ...rest } = repoOrder;
    expect(buildBoardPayload(rest)?.total).toBe(2 * 80 + 30);
  });

  it("returns null for an order without an integer number (a draft)", () => {
    expect(buildBoardPayload({ ...repoOrder, orderNumber: null })).toBeNull();
    expect(buildBoardPayload(null)).toBeNull();
  });
});

describe("notifyOrderBoard", () => {
  it("no-ops (no request) when no board URL is configured", async () => {
    const fetchImpl = vi.fn();
    const sent = await notifyOrderBoard(repoOrder, { url: "", fetchImpl });
    expect(sent).toBe(false);
    expect(fetchImpl).not.toHaveBeenCalled();
  });

  it("POSTs the payload to {url}/api/orders and reports success on 2xx", async () => {
    const fetchImpl = vi.fn().mockResolvedValue({ ok: true, status: 201 });
    const sent = await notifyOrderBoard(repoOrder, { url: "http://localhost:4321/", fetchImpl });

    expect(sent).toBe(true);
    expect(fetchImpl).toHaveBeenCalledTimes(1);
    const [calledUrl, init] = fetchImpl.mock.calls[0];
    expect(calledUrl).toBe("http://localhost:4321/api/orders");
    expect(init.method).toBe("POST");
    expect(JSON.parse(init.body)).toMatchObject({ orderNumber: 205, status: "CONFIRMED" });
  });

  it("swallows network errors and returns false", async () => {
    const fetchImpl = vi.fn().mockRejectedValue(new Error("ECONNREFUSED"));
    const warn = vi.fn();
    const sent = await notifyOrderBoard(repoOrder, {
      url: "http://localhost:4321",
      fetchImpl,
      logger: { warn }
    });
    expect(sent).toBe(false);
    expect(warn).toHaveBeenCalled();
  });
});

