class DashboardUrlTest {

    @Test
    fun `explicit dashboard url wins and is returned as-is when it has a scheme`() {
        val url = DashboardUrl.resolve(dashboardUrl = "http://192.168.1.50:4321", baseUrl = "http://192.168.1.50:3000")
        assertEquals("http://192.168.1.50:4321", url)
    }

    @Test
    fun `explicit dashboard url without a scheme gets http prefixed`() {
        assertEquals("http://board.local:4321", DashboardUrl.resolve("board.local:4321", ""))
    }

    @Test
    fun `https dashboard url is preserved`() {
        assertEquals("https://kds.example.com", DashboardUrl.resolve("https://kds.example.com", ""))
    }

    @Test
    fun `blank dashboard url derives host from the API base url on the default port`() {
        val url = DashboardUrl.resolve(dashboardUrl = "", baseUrl = "http://192.168.1.50:3000")
        assertEquals("http://192.168.1.50:${DashboardUrl.DEFAULT_PORT}", url)
    }

    @Test
    fun `deriving works when the API base url has no scheme or path`() {
        assertEquals("http://10.0.0.9:4321", DashboardUrl.resolve("", "10.0.0.9:3000"))
        assertEquals("http://10.0.0.9:4321", DashboardUrl.resolve("", "http://10.0.0.9:3000/api/"))
    }

    @Test
    fun `both blank yields null (nothing to open)`() {
        assertNull(DashboardUrl.resolve(dashboardUrl = "", baseUrl = ""))
        assertNull(DashboardUrl.resolve(dashboardUrl = "   ", baseUrl = "   "))
    }
