import type { Request } from "express";
import { requireFields } from "../../../shared/validation";
import { assertPrinterBridgeAuth } from "./printing";

/**
 * Validate a display-board backfill request. Same trusted-device auth as the
 * printer bridge (x-printer-token) — the board is another LAN device, not a
 * per-user actor — scoped to one kitchen.
 */
export function validateGetOrderBoardRequest(request: Request) {
  assertPrinterBridgeAuth(request);

  const input = { kitchenId: request.params.kitchenId };
  requireFields(input, ["kitchenId"]);

  return { kitchenId: input.kitchenId };
}

import { repositories } from "../../infrastructure/container";
import { buildBoardPayload } from "../../integrations/dashboard/order-board-notifier";

/**
 * Current active orders for a kitchen, shaped for the display board — the
 * backfill the dashboard pulls on startup so a restarted board immediately
 * shows every already-confirmed ticket (not just ones that change afterwards).
 *
 * Reuses the same "active" query as the rest of the app (CONFIRMED +
 * IN_PROCESS_OF_DELIVERY) and the same `buildBoardPayload` mapping the push
 * notifier uses, so the backfill and the live pushes are byte-for-byte
 * consistent.
 */
export async function executeGetOrderBoard(input: any, deps: any = repositories) {
  const orders = await deps.orders.query({ filter: "active", kitchenId: input.kitchenId });
  const boardOrders = orders
    .map((order: any) => buildBoardPayload(order))
    .filter((order: any) => order !== null);

  return { ok: true, orders: boardOrders };
}

import { Router } from "express";
import { getStatusCodeForResult } from "../../../shared/errors";
import { executeGetOrderBoard } from "../../../application/usecases/board";
import { validateGetOrderBoardRequest } from "../validators/board";

export function createBoardRouter() {
  const router = Router();

  // Display-board backfill: active tickets for a kitchen, board-shaped.
  router.get("/kitchens/:kitchenId/order-board", async (request, response, next) => {
    try {
      const input = validateGetOrderBoardRequest(request);
      const result = await executeGetOrderBoard(input);
      response.status(getStatusCodeForResult(result)).json(result);
    } catch (error) {
      next(error);
    }
  });

  return router;
}

