import { describe, expect, it, vi } from "vitest";
import { executeGetOrderBoard } from "../../src/application/usecases/board.ts";

describe("executeGetOrderBoard", () => {
  it("queries active orders for the kitchen and maps them to board payloads", async () => {
    const query = vi.fn().mockResolvedValue([
      {
        id: "1", orderNumber: 101, status: "CONFIRMED", deliveryType: "PICKUP", total: 190,
        items: [{ nameSnapshot: "Hamburguesa", quantity: 2, unitPriceSnapshot: 95 }]
      },
      {
        id: "2", orderNumber: 102, status: "IN_PROCESS_OF_DELIVERY", deliveryType: "DELIVERY", total: 50,
        items: [{ nameSnapshot: "Refresco", quantity: 1, unitPriceSnapshot: 50 }]
      }
    ]);

    const result = await executeGetOrderBoard({ kitchenId: "7" }, { orders: { query } });

    expect(query).toHaveBeenCalledWith({ filter: "active", kitchenId: "7" });
    expect(result.ok).toBe(true);
    expect(result.orders).toEqual([
      { orderNumber: 101, status: "CONFIRMED", deliveryType: "PICKUP", items: [{ name: "Hamburguesa", quantity: 2, unitPrice: 95 }], total: 190 },
      { orderNumber: 102, status: "IN_PROCESS_OF_DELIVERY", deliveryType: "DELIVERY", items: [{ name: "Refresco", quantity: 1, unitPrice: 50 }], total: 50 }
    ]);
  });

  it("drops orders that can't be shown on the board (e.g. no order number)", async () => {
    const query = vi.fn().mockResolvedValue([
      { id: "1", orderNumber: null, status: "CONFIRMED", items: [] },
      { id: "2", orderNumber: 103, status: "CONFIRMED", deliveryType: "PICKUP", items: [], total: 0 }
    ]);

    const result = await executeGetOrderBoard({ kitchenId: "7" }, { orders: { query } });

    expect(result.orders.map((o: any) => o.orderNumber)).toEqual([103]);
  });
});

// Pulls the active-order backfill from kitchen-api so a freshly started board
// immediately shows every already-confirmed ticket (not just ones that change
// after boot). Authenticates as a trusted LAN device with the printer token
// (x-printer-token) — the same credential the printer-android app holds.
//
// Returns a `backfill()` function, or null when not configured (backfill off).

/**
 * @param {object} opts
 * @param {string} opts.url         kitchen-api base URL, e.g. http://192.168.1.50:3000
 * @param {string} opts.kitchenId   kitchen this board displays
 * @param {string} opts.printerToken PRINTER_BRIDGE_API_KEY
 * @param {string} [opts.tokenHeader] auth header name (default x-printer-token)
 * @param {typeof fetch} [opts.fetchImpl]
 * @param {number} [opts.timeoutMs]
 * @param {{warn?: Function}} [opts.logger]
 */
export function createKitchenApiBackfill(opts = {}) {
  const url = (opts.url ?? "").trim();
  const kitchenId = (opts.kitchenId ?? "").trim();
  const printerToken = (opts.printerToken ?? "").trim();
  if (!url || !kitchenId || !printerToken) {
    return null; // backfill disabled
  }

  const tokenHeader = opts.tokenHeader ?? "x-printer-token";
  const fetchImpl = opts.fetchImpl ?? globalThis.fetch;
  const timeoutMs = opts.timeoutMs ?? 3000;
  const logger = opts.logger ?? console;
  const endpoint = `${url.replace(/\/+$/, "")}/kitchens/${encodeURIComponent(kitchenId)}/order-board`;

  return async function backfill() {
    if (typeof fetchImpl !== "function") return [];
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    try {
      const response = await fetchImpl(endpoint, {
        headers: { [tokenHeader]: printerToken },
        signal: controller.signal
      });
      if (!response?.ok) {
        logger.warn?.(`[backfill] kitchen-api returned ${response?.status} for ${endpoint}`);
        return [];
      }
      const body = await response.json();
      return Array.isArray(body?.orders) ? body.orders : [];
    } catch (error) {
      logger.warn?.(`[backfill] failed: ${error?.message ?? error}`);
      return [];
    } finally {
      clearTimeout(timer);
    }
  };
}

