if (isMain) {
  const port = Number(process.argv[2] || process.env.DASHBOARD_PORT || 4321);
  const enableDemo = process.env.DASHBOARD_DEMO === "1";

  // Backfill from kitchen-api on startup (unset env ⇒ disabled). Uses the
  // printer token, the same trusted-device credential the printer app holds.
  const backfill = createKitchenApiBackfill({
    url: process.env.KITCHEN_API_URL,
    kitchenId: process.env.KITCHEN_ID,
    printerToken: process.env.KITCHEN_DASHBOARD_PRINTER_TOKEN || process.env.PRINTER_BRIDGE_API_KEY,
    tokenHeader: process.env.KITCHEN_API_PRINTER_TOKEN_HEADER || "x-printer-token"
  });

  const { server, runBackfill } = createBoardServer({ enableDemo, backfill });
  server.listen(port, async () => {
    // eslint-disable-next-line no-console
    console.log(`[kitchen-dashboard] listening on http://localhost:${port}${enableDemo ? " (demo mode)" : ""}`);
    if (!backfill) return;
    // A few spaced attempts so a board that boots before kitchen-api still
    // fills in; upserts are idempotent so retrying is harmless.
    for (let attempt = 1; attempt <= 3; attempt += 1) {
      const seeded = await runBackfill();
      // eslint-disable-next-line no-console
      console.log(`[kitchen-dashboard] backfill attempt ${attempt}: ${seeded} ticket(s)`);
      if (seeded > 0) break;
      await new Promise((r) => setTimeout(r, 2000));
    }
  });
}

