import { test } from "node:test";
import assert from "node:assert/strict";
import http from "node:http";
import { createBoardServer } from "../src/server.mjs";
import { createKitchenApiBackfill } from "../src/kitchen-api-client.mjs";

function get(base, path, headers = {}) {
  return new Promise((resolve, reject) => {
    http.get(`${base}${path}`, { headers }, (res) => {
      const chunks = [];
      res.on("data", (c) => chunks.push(c));
      res.on("end", () => resolve({ status: res.statusCode, body: JSON.parse(Buffer.concat(chunks).toString() || "{}") }));
    }).on("error", reject);
  });
}

test("runBackfill seeds the store from the injected backfill source", async () => {
  const backfill = async () => [
    { orderNumber: 301, status: "CONFIRMED", deliveryType: "PICKUP", items: [], total: 0 },
    { orderNumber: 302, status: "IN_PROCESS_OF_DELIVERY", deliveryType: "DELIVERY", items: [], total: 0 },
    { orderNumber: 303, status: "DELIVERED", deliveryType: "PICKUP", items: [], total: 0 } // terminal → dropped
  ];
  const { store, runBackfill } = createBoardServer({ backfill });

  const seeded = await runBackfill();
  assert.equal(seeded, 3);
  // Terminal order does not linger on the board.
  assert.deepEqual(store.board().map((o) => o.orderNumber), [301, 302]);
});

test("a screen that connects after backfill gets the seeded orders in its snapshot", async () => {
  const { server, runBackfill } = createBoardServer({
    backfill: async () => [{ orderNumber: 401, status: "CONFIRMED", deliveryType: "PICKUP", items: [], total: 0 }]
  });
  await new Promise((r) => server.listen(0, "127.0.0.1", r));
  const base = `http://127.0.0.1:${server.address().port}`;
  await runBackfill();

  const res = await get(base, "/api/orders");
  assert.deepEqual(res.body.orders.map((o) => o.orderNumber), [401]);
  server.close();
});

test("POST /api/backfill re-pulls on demand", async () => {
  let calls = 0;
  const { server } = createBoardServer({
    backfill: async () => { calls += 1; return [{ orderNumber: 501, status: "CONFIRMED", deliveryType: "PICKUP", items: [], total: 0 }]; }
  });
  await new Promise((r) => server.listen(0, "127.0.0.1", r));
  const base = `http://127.0.0.1:${server.address().port}`;

  const res = await new Promise((resolve, reject) => {
    const req = http.request(`${base}/api/backfill`, { method: "POST" }, (r) => {
      const chunks = [];
      r.on("data", (c) => chunks.push(c));
      r.on("end", () => resolve({ status: r.statusCode, body: JSON.parse(Buffer.concat(chunks).toString()) }));
    });
    req.on("error", reject);
    req.end();
  });
  assert.equal(res.status, 200);
  assert.equal(res.body.backfilled, 1);
  assert.equal(calls, 1);
  server.close();
});

test("createKitchenApiBackfill returns null when unconfigured", () => {
  assert.equal(createKitchenApiBackfill({}), null);
  assert.equal(createKitchenApiBackfill({ url: "http://x", kitchenId: "" , printerToken: "t" }), null);
});

test("createKitchenApiBackfill calls the order-board endpoint with the printer token", async () => {
  let capturedUrl, capturedHeaders;
  const fetchImpl = async (url, init) => {
