// Combined smoke test for the kitchen-orders-dashboard feature.
//
// Exercises the whole board pipeline end-to-end with zero dependencies: it
// starts a real board server and drives it with the exact HTTP calls that
// kitchen-api's `notifyOrderBoard` makes (POST /api/orders with the full order
// snapshot) as an order moves CONFIRMED -> ready -> DELIVERED. Asserts the board
// adds, updates-in-place, and drops the ticket, and that a draft (no order
// number) is refused.
//
// Run: `npm run smoke`  (exits non-zero on any failed assertion)

import assert from "node:assert/strict";
import { createBoardServer } from "../src/server.mjs";

const { server } = createBoardServer({ enableDemo: false });
await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
const { port } = server.address();
const base = `http://127.0.0.1:${port}`;

// Mirror of what kitchen-api's notifyOrderBoard sends.
async function push(order) {
  const res = await fetch(`${base}/api/orders`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(order)
  });
  return res.status;
}

async function board() {
  const res = await fetch(`${base}/api/orders`);
  return (await res.json()).orders;
}

const order = {
  orderNumber: 42,
  deliveryType: "PICKUP",
  total: 190,
  items: [{ name: "Hamburguesa Doble", quantity: 2, unitPrice: 95 }]
};

let step = 0;
const ok = (label) => console.log(`  ✓ ${label}`);
try {
  // 1) Confirm → ticket appears as "Preparando".
  step = 1;
  assert.equal(await push({ ...order, status: "CONFIRMED" }), 201);
  let b = await board();
  assert.equal(b.length, 1);
  assert.equal(b[0].orderNumber, 42);
  assert.equal(b[0].badge.label, "Preparando");
  ok("CONFIRMED → ticket #42 shows 'Preparando'");

  // 2) Ready → same ticket, badge updated in place (still #42, still 1 card).
  step = 2;
  await push({ ...order, status: "IN_PROCESS_OF_DELIVERY" });
  b = await board();
  assert.equal(b.length, 1);
  assert.equal(b[0].orderNumber, 42);
  assert.equal(b[0].badge.label, "Listo para recoger");
  ok("IN_PROCESS_OF_DELIVERY → badge flips to 'Listo para recoger' in place");

  // 3) Delivered → ticket leaves the board.
  step = 3;
  await push({ ...order, status: "DELIVERED" });
  assert.equal((await board()).length, 0);
  ok("DELIVERED → ticket drops off the board");

  // 4) A draft with no order number is refused (never shown as order 0).
  step = 4;
  assert.equal(await push({ ...order, orderNumber: null, status: "DRAFT" }), 400);
  assert.equal((await board()).length, 0);
  ok("DRAFT without a number → rejected (400), board still empty");

  console.log("\nSMOKE OK — dashboard pipeline healthy");
  server.close();
} catch (error) {
  console.error(`\nSMOKE FAILED at step ${step}: ${error.message}`);
  server.close();
  process.exit(1);
}

