package com.aomu.printerandroid.dashboard

/**
 * Works out which URL the "Abrir tablero de cocina" button should open.
 *
 * The kitchen orders display board (KDS) is a small web app that normally runs
 * on the same host as the Kitchen API (the Docker host), just on a different
 * port. So the admin usually doesn't need to type a second URL: if the dashboard
 * URL is left blank we reuse the API host and swap in the dashboard port.
 *
 * Pure (no Android) so the resolution rules are covered by plain JUnit tests.
 */
object DashboardUrl {

    /** Default port the kitchen-dashboard server listens on. */
    const val DEFAULT_PORT = 4321

    /**
     * Resolve the URL to open, or null if nothing usable is configured.
     * An explicit [dashboardUrl] always wins (normalized with a scheme);
     * otherwise the board is assumed to live on [baseUrl]'s host at
     * [DEFAULT_PORT].
     */
    fun resolve(dashboardUrl: String, baseUrl: String): String? {
        val explicit = dashboardUrl.trim()
        if (explicit.isNotEmpty()) {
            return normalize(explicit)
        }
        val host = hostOf(baseUrl) ?: return null
        return "http://$host:$DEFAULT_PORT"
    }

    /** Prefix a bare host/URL with http:// so it's a valid, launchable URI. */
    private fun normalize(url: String): String {
        val trimmed = url.trim()
        return if (trimmed.startsWith("http://") || trimmed.startsWith("https://")) {
            trimmed
        } else {
            "http://$trimmed"
        }
    }

    /** Extract just the host from an API base URL (dropping scheme, port, path). */
    private fun hostOf(baseUrl: String): String? {
        val trimmed = baseUrl.trim()
        if (trimmed.isEmpty()) {
            return null
        }
        val afterScheme = normalize(trimmed).substringAfter("://")
        val host = afterScheme
            .substringBefore("/")
            .substringBefore("?")
            .substringBefore(":")
            .trim()
        return host.ifEmpty { null }
    }
}

