import com.aomu.printerandroid.api.ApiSettingsStore
import com.aomu.printerandroid.dashboard.DashboardUrl

/**
 * In-app WebView of the kitchen orders dashboard, so a kitchen without a printer
 * can still use the app. URL is [DashboardUrl.resolve] (dashboardUrl, or the API
 * base + "/dashboard"). Cleartext http is already allowed app-wide
 * (usesCleartextTraffic in the manifest), same as the API polling.
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun DashboardScreen(onBack: () -> Unit) {
    val context = LocalContext.current
    val store = remember { ApiSettingsStore(context.applicationContext) }

    var url by remember { mutableStateOf<String?>(null) }
    var loaded by remember { mutableStateOf(false) }
    var failed by remember { mutableStateOf(false) }
    var reloadKey by remember { mutableIntStateOf(0) }

    LaunchedEffect(Unit) {
        val settings = store.currentSettings()
        url = DashboardUrl.resolve(settings.dashboardUrl, settings.baseUrl)
        loaded = true
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("Dashboard") },
                navigationIcon = { TextButton(onClick = onBack) { Text("Atrás") } }
            )
        }
    ) { padding ->
        Box(modifier = Modifier.fillMaxSize().padding(padding)) {
            val current = url
            when {
                !loaded -> Unit
                current == null -> CenteredText(
                    "Configura la URL de la API en Configuración para ver el dashboard."
                )
                failed -> Column(
                    modifier = Modifier.fillMaxSize().padding(24.dp),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.Center
                ) {
                    Text(
                        "No se pudo cargar el dashboard.\n$current",
                        color = MaterialTheme.colorScheme.error,
                        textAlign = TextAlign.Center,
                        style = MaterialTheme.typography.bodyLarge
                    )
                    Button(onClick = { failed = false; reloadKey++ }) { Text("Reintentar") }
                }
                else -> key(reloadKey) {
                    AndroidView(
                        modifier = Modifier.fillMaxSize(),
                        factory = { ctx ->
                            WebView(ctx).apply {
                                settings.javaScriptEnabled = true
                                settings.domStorageEnabled = true
                                webViewClient = object : WebViewClient() {
                                    override fun onReceivedError(
                                        view: WebView?,
                                        request: WebResourceRequest?,
                                        error: WebResourceError?
                                    ) {
                                        if (request?.isForMainFrame == true) failed = true
                                    }
                                }
                                loadUrl(current)
                            }
                        }
                    )
                }
            }
        }
    }
}

@Composable
private fun CenteredText(message: String) {
    Box(modifier = Modifier.fillMaxSize().padding(24.dp), contentAlignment = Alignment.Center) {
        Text(message, textAlign = TextAlign.Center, style = MaterialTheme.typography.bodyLarge)
    }
}

